/**
 * WordPress `user_login` only allows certain characters (letters, numbers, _, -).
 * Email local parts like `user+1` contain `+`, which the REST API rejects, so
 * Firebase signup can succeed while WordPress user creation fails.
 */
export function sanitizeWordPressUsernamePrefix(localPart: string): string {
  const cleaned = localPart
    .toLowerCase()
    .replace(/[^a-z0-9]/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_|_$/g, "");
  return cleaned.length > 0 ? cleaned : "user";
}

/**
 * Builds a safe WordPress username from an email address.
 */
export function wordPressUsernameFromEmail(email: string): string {
  const local = email.split("@")[0] ?? "user";
  const prefix = sanitizeWordPressUsernamePrefix(local);
  const suffix = Math.random().toString(36).substring(2, 6);
  return `${prefix}_${suffix}`;
}
