/**
 * Interactive Hebrew Word Explorer
 * Full-screen overlay for exploring Hebrew verse words via draggable letter tiles.
 * Users can combine tiles to discover deeper meanings (e.g., bet+resh=son).
 */

import React, { useState, useEffect, useCallback } from "react";
import ReactDOM from "react-dom";
import {
  DndContext,
  DragEndEvent,
  DragStartEvent,
  DragOverEvent,
  PointerSensor,
  TouchSensor,
  useSensor,
  useSensors,
  pointerWithin,
} from "@dnd-kit/core";
import Box from "@mui/material/Box";
import Typography from "@mui/material/Typography";
import IconButton from "@mui/material/IconButton";
import CloseIcon from "@mui/icons-material/Close";
import CircularProgress from "@mui/material/CircularProgress";
import {
  fetchHebrewWordsForVerse,
  getStrongsDefinition,
  VerseWord,
} from "../../services/strongsService";
import {
  decomposeHebrewWord,
  getLetterMeaning,
  getCombinationMeaning,
  getFallbackCombinationMeaning,
  lettersMatchWord,
  getVerseRevealedSentence,
  getBereshitPhraseMapping,
  HEBREW_FONT,
  normalizeLetter,
} from "../../data/hebrewLetterMeanings";
import HebrewLetterTile, { HebrewTileData } from "./HebrewLetterTile";
import { useTranslation } from "../../hooks/useTranslation";
import { translateBookName } from "../../utils/bookTranslations";

interface HebrewExplorerProps {
  open: boolean;
  onClose: () => void;
  verse: {
    book: string;
    chapter: number;
    verse: number;
    text: string;
  } | null;
  userLanguage: string;
}

let tileIdCounter = 0;

function createTilesFromWords(
  words: VerseWord[],
  userLanguage: string
): HebrewTileData[] {
  const tiles: HebrewTileData[] = [];
  words.forEach((word, wordIndex) => {
    const letters = decomposeHebrewWord(word.hebrew);
    if (letters.length === 0) {
      // Fallback: use whole word as single tile
      tiles.push({
        id: `tile-${tileIdCounter++}`,
        letters: [word.hebrew],
        meaning:
          word.entry?.translations?.[userLanguage] ||
          word.entry?.definition ||
          word.hebrew,
        wordIndex,
      });
    } else {
      letters.forEach((letter) => {
        tiles.push({
          id: `tile-${tileIdCounter++}`,
          letters: [letter],
          meaning: getLetterMeaning(letter, userLanguage),
          wordIndex,
        });
      });
    }
  });
  return tiles;
}

const HebrewExplorer: React.FC<HebrewExplorerProps> = ({
  open,
  onClose,
  verse,
  userLanguage,
}) => {
  const { t } = useTranslation();
  const [hebrewWords, setHebrewWords] = useState<VerseWord[]>([]);
  const [loading, setLoading] = useState(false);
  const [tiles, setTiles] = useState<HebrewTileData[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [overId, setOverId] = useState<string | null>(null);
  const [hoveredLetters, setHoveredLetters] = useState<Set<string>>(new Set());

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: { distance: 8 },
    }),
    useSensor(TouchSensor, {
      activationConstraint: { delay: 200, tolerance: 8 },
    })
  );

  useEffect(() => {
    if (!open || !verse) {
      setTiles([]);
      return;
    }
    setLoading(true);
    const chapter = Number(verse.chapter);
    const verseNum = Number(verse.verse);
    fetchHebrewWordsForVerse(verse.book, chapter, verseNum)
      .then((words) => {
        // Genesis 1:1: Strong's H7225 gives רֵאשִׁית without the ב prefix.
        // Prepend ב to first word so we have full בְּרֵאשִׁית for pictographic exploration (ב+ר=son).
        const bookNorm = String(verse.book || "").toLowerCase().trim().replace(/\s+/g, "");
        const key = `${bookNorm} ${chapter}:${verseNum}`;
        if ((key === "genesis 1:1" || key === "genesis1:1") && words.length > 0) {
          const firstLetters = decomposeHebrewWord(words[0].hebrew);
          const hasBet = firstLetters.some((l) => l === "ב" || l === "בּ");
          if (!hasBet && firstLetters[0] === "ר") {
            words = [
              { ...words[0], hebrew: "\u05d1" + words[0].hebrew },
              ...words.slice(1),
            ];
          }
        }
        setHebrewWords(words);
        tileIdCounter = 0;
        const newTiles = createTilesFromWords(words, userLanguage);
        setTiles(newTiles);
      })
      .catch((err) => {
        console.error("Failed to fetch Hebrew words:", err);
        setTiles([]);
      })
      .finally(() => setLoading(false));
  }, [open, verse?.book, verse?.chapter, verse?.verse, userLanguage]);

  // Re-enable scroll when explorer closes (handles close-while-dragging)
  useEffect(() => {
    if (!open) {
      document.body.style.overflow = "";
      document.body.style.touchAction = "";
    }
  }, [open]);

  const handleDragStart = useCallback((event: DragStartEvent) => {
    setActiveId(String(event.active.id));
    // Disable scroll on mobile while dragging to prevent page scroll
    document.body.style.overflow = "hidden";
    document.body.style.touchAction = "none";
  }, []);

  const handleDragOver = useCallback((event: DragOverEvent) => {
    setOverId(event.over ? String(event.over.id) : null);
  }, []);

  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      const { active, over } = event;
      setActiveId(null);
      setOverId(null);
      // Re-enable scroll
      document.body.style.overflow = "";
      document.body.style.touchAction = "";

      if (!over || active.id === over.id) return;

      const activeTile = tiles.find((t) => t.id === active.id);
      const overTile = tiles.find((t) => t.id === over.id);
      if (!activeTile || !overTile) return;

      // Try both orderings: A+B and B+A (getCombinationMeaning also tries permutations for 3+ letters)
      const combinedLettersA = activeTile.letters.concat(overTile.letters);
      const combinedLettersB = overTile.letters.concat(activeTile.letters);
      let combinedMeaning =
        getCombinationMeaning(combinedLettersA, userLanguage) ||
        getCombinationMeaning(combinedLettersB, userLanguage);

      // Use fallback (letter meanings joined) when no exact combination exists
      if (!combinedMeaning) {
        combinedMeaning = getFallbackCombinationMeaning(
          combinedLettersA,
          userLanguage
        );
      }

      const letters = getCombinationMeaning(combinedLettersA, userLanguage)
        ? combinedLettersA
        : combinedLettersB;

      // When combined tile = full word, use Strong's definition and original Hebrew
      let meaning = combinedMeaning;
      let displayHebrew: string | undefined;
      const matchedWord = hebrewWords.find((w) => lettersMatchWord(letters, w.hebrew));
      if (matchedWord) {
        meaning = getStrongsDefinition(matchedWord.entry, userLanguage) || combinedMeaning;
        displayHebrew = matchedWord.hebrew;
      }

      const newTile: HebrewTileData = {
        id: `tile-${tileIdCounter++}`,
        letters,
        meaning,
        wordIndex: activeTile.wordIndex,
        displayHebrew,
      };

      // Insert at position of first removed tile (keeps logical order)
      setTiles((prev) => {
        const filtered = prev.filter(
          (t) => t.id !== active.id && t.id !== over.id
        );
        const firstIdx = prev.findIndex(
          (t) => t.id === active.id || t.id === over.id
        );
        const insertAt = firstIdx >= 0 ? Math.min(firstIdx, filtered.length) : filtered.length;
        return [
          ...filtered.slice(0, insertAt),
          newTile,
          ...filtered.slice(insertAt),
        ];
      });
    },
    [tiles, userLanguage, hebrewWords]
  );

  const handleDragCancel = useCallback(() => {
    setActiveId(null);
    setOverId(null);
    // Re-enable scroll
    document.body.style.overflow = "";
    document.body.style.touchAction = "";
  }, []);

  const handleDestructure = useCallback(
    (tileId: string) => {
      const tile = tiles.find((t) => t.id === tileId);
      if (!tile || tile.letters.length <= 1) return;

      const newTiles: HebrewTileData[] = tile.letters.map((letter) => ({
        id: `tile-${tileIdCounter++}`,
        letters: [letter],
        meaning: getLetterMeaning(letter, userLanguage),
        wordIndex: tile.wordIndex,
      }));

      setTiles((prev) => {
        const idx = prev.findIndex((t) => t.id === tileId);
        if (idx < 0) return prev;
        return [
          ...prev.slice(0, idx),
          ...newTiles,
          ...prev.slice(idx + 1),
        ];
      });
    },
    [tiles, userLanguage]
  );

  if (!open) return null;

  const hebrewVerseText = hebrewWords.map((w) => w.hebrew).join(" ");

  // Render into document.body via portal so we don't inherit opacity from parent Container
  return ReactDOM.createPortal(
    <Box
      sx={{
        position: "fixed",
        inset: 0,
        zIndex: 1300,
        backgroundColor: (theme) =>
          theme.palette.mode === "dark"
            ? "rgba(18, 18, 18, 0.98)"
            : "rgba(255, 255, 255, 0.98)",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        overflowY: activeId ? "hidden" : "auto",
        touchAction: activeId ? "none" : "auto",
        WebkitOverflowScrolling: "touch",
        py: 4,
        px: 2,
        animation: "fadeIn 0.3s ease-out",
        "@keyframes fadeIn": {
          from: { opacity: 0 },
          to: { opacity: 1 },
        },
      }}
    >
      <IconButton
        onClick={onClose}
        sx={{
          position: "absolute",
          top: 16,
          right: 16,
          color: "text.primary",
        }}
        aria-label={t("hebrewExplorer.close")}
      >
        <CloseIcon />
      </IconButton>

      <Typography variant="h5" sx={{ mb: 1, fontWeight: 600 }}>
        {verse
          ? `${t("hebrewExplorer.title")} — ${translateBookName(verse.book, t)} ${verse.chapter}:${verse.verse}`
          : t("hebrewExplorer.title")}
      </Typography>

      {verse?.text && (
        <Typography
          variant="body1"
          sx={{
            mb: 2,
            fontStyle: "italic",
            color: "text.secondary",
            maxWidth: 600,
            textAlign: "center",
          }}
        >
          "{verse.text}"
        </Typography>
      )}

      {loading ? (
        <Box sx={{ display: "flex", alignItems: "center", gap: 2, py: 4 }}>
          <CircularProgress size={24} />
          <Typography variant="body2" color="text.secondary">
            {t("common.loading")}
          </Typography>
        </Box>
      ) : (
        <>
          {hebrewVerseText && (
            <Typography
              variant="h4"
              component="div"
              sx={{
                fontFamily: HEBREW_FONT,
                direction: "rtl",
                textAlign: "right",
                fontSize: { xs: "1.75rem", md: "2.25rem" },
                lineHeight: 1.8,
                mb: 3,
                maxWidth: 800,
              }}
            >
              {hebrewVerseText}
            </Typography>
          )}

          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            {t("hebrewExplorer.dragToCombine")}
          </Typography>

          {verse &&
            getVerseRevealedSentence(
              verse.book,
              verse.chapter,
              verse.verse,
              userLanguage
            ) && (
              <Box
                sx={{
                  mb: 3,
                  maxWidth: 720,
                  px: 2,
                  py: 2,
                  borderRadius: 2,
                  backgroundColor: (theme) =>
                    theme.palette.mode === "dark"
                      ? "rgba(255, 255, 255, 0.06)"
                      : "rgba(0, 0, 0, 0.04)",
                  borderLeft: (theme) =>
                    `4px solid ${theme.palette.primary.main}`,
                }}
              >
                <Typography
                  variant="overline"
                  sx={{
                    display: "block",
                    mb: 1.5,
                    color: "primary.main",
                    fontWeight: 600,
                  }}
                >
                  {t("hebrewExplorer.revealedInsight")}
                </Typography>
                <Typography
                  variant="body1"
                  component="span"
                  sx={{
                    fontStyle: "italic",
                    color: "text.primary",
                    lineHeight: 1.8,
                  }}
                >
                  "
                  {(() => {
                    const phraseMapping = getBereshitPhraseMapping(
                      userLanguage
                    );
                    const key = `${String(verse.book).toLowerCase()} ${verse.chapter}:${verse.verse}`;
                    const hasMapping = key === "genesis 1:1";
                    if (hasMapping && phraseMapping.length > 0) {
                      return phraseMapping.map((item, idx) => (
                        <Box
                          key={idx}
                          component="span"
                          onMouseEnter={() =>
                            setHoveredLetters(new Set(item.letters))
                          }
                          onMouseLeave={() =>
                            setHoveredLetters(new Set())
                          }
                          sx={{
                            borderBottom: (theme) =>
                              `2px dotted ${theme.palette.primary.main}`,
                            cursor: "help",
                            "&:hover": {
                              backgroundColor: (theme) =>
                                theme.palette.mode === "dark"
                                  ? "rgba(25, 118, 210, 0.2)"
                                  : "rgba(25, 118, 210, 0.1)",
                            },
                          }}
                          title={
                            item.letters.length > 0
                              ? `${t("hebrewExplorer.hoverToHighlight")}`
                              : undefined
                          }
                        >
                          {item.phrase}
                          <Box
                            component="span"
                            sx={{
                              fontFamily: HEBREW_FONT,
                              direction: "rtl",
                              fontSize: "0.75em",
                              ml: 0.5,
                              opacity: 0.85,
                              color: "primary.main",
                              fontWeight: 600,
                            }}
                          >
                            [{item.letters.join("")}]
                          </Box>
                        </Box>
                      ));
                    }
                    return getVerseRevealedSentence(
                      verse.book,
                      verse.chapter,
                      verse.verse,
                      userLanguage
                    );
                  })()}
                  "
                </Typography>
                {verse &&
                  `${String(verse.book).toLowerCase()} ${verse.chapter}:${verse.verse}` ===
                    "genesis 1:1" && (
                    <>
                      <Typography
                        variant="caption"
                        sx={{
                          display: "block",
                          mt: 1,
                          color: "text.secondary",
                          fontStyle: "normal",
                        }}
                      >
                        {t("hebrewExplorer.hoverToHighlight")}
                      </Typography>
                      <Typography
                        variant="caption"
                        sx={{
                          display: "block",
                          mt: 0.5,
                          color: "primary.main",
                          fontFamily: HEBREW_FONT,
                          fontSize: "0.75rem",
                        }}
                      >
                        {t("hebrewExplorer.bereshitHint")}
                      </Typography>
                    </>
                  )}
              </Box>
            )}

          <DndContext
            sensors={sensors}
            collisionDetection={pointerWithin}
            onDragStart={handleDragStart}
            onDragOver={handleDragOver}
            onDragEnd={handleDragEnd}
            onDragCancel={handleDragCancel}
          >
            <Box sx={{ maxWidth: 920 }}>
              {hebrewWords.length > 0
                ? hebrewWords.map((word, wordIndex) => {
                    const wordTiles = tiles.filter(
                      (t) => t.wordIndex === wordIndex
                    );
                    if (wordTiles.length === 0) return null;
                    return (
                      <Box
                        key={wordIndex}
                        sx={{
                          mb: 3,
                          p: 2,
                          borderRadius: 2,
                          backgroundColor: (theme) =>
                            theme.palette.mode === "dark"
                              ? "rgba(255, 255, 255, 0.03)"
                              : "rgba(0, 0, 0, 0.02)",
                          border: (theme) =>
                            `1px solid ${
                              theme.palette.mode === "dark"
                                ? "rgba(255, 255, 255, 0.08)"
                                : "rgba(0, 0, 0, 0.06)"
                            }`,
                        }}
                      >
                        <Box
                          sx={{
                            display: "flex",
                            justifyContent: "space-between",
                            alignItems: "flex-start",
                            gap: 2,
                            mb: 1.5,
                          }}
                        >
                          <Typography
                            variant="subtitle2"
                            sx={{
                              fontFamily: HEBREW_FONT,
                              direction: "rtl",
                              fontSize: "1.25rem",
                              color: "text.secondary",
                            }}
                          >
                            {word.hebrew}
                          </Typography>
                          <Typography
                            variant="caption"
                            sx={{
                              flexShrink: 0,
                              maxWidth: "55%",
                              textAlign: "right",
                              color: "text.secondary",
                              fontStyle: "italic",
                              lineHeight: 1.4,
                            }}
                          >
                            {getStrongsDefinition(word.entry, userLanguage)}
                          </Typography>
                        </Box>
                        <Box
                          sx={{
                            display: "flex",
                            flexWrap: "wrap",
                            gap: 0.5,
                            justifyContent: "flex-start",
                          }}
                        >
                          {wordTiles.map((tile) => {
                            const isHighlighted =
                              hoveredLetters.size > 0 &&
                              tile.letters.some((l) =>
                                hoveredLetters.has(normalizeLetter(l))
                              );
                            return (
                              <HebrewLetterTile
                                key={tile.id}
                                tile={tile}
                                userLanguage={userLanguage}
                                isOver={overId === tile.id && activeId !== tile.id}
                                isHighlighted={isHighlighted}
                                hebrewFont={HEBREW_FONT}
                                onDestructure={handleDestructure}
                                destructureTooltip={t("hebrewExplorer.clickToSplit")}
                              />
                            );
                          })}
                        </Box>
                      </Box>
                    );
                  })
                : null}
              {hebrewWords.length === 0 && tiles.length > 0 && (
                <Box
                  sx={{
                    display: "flex",
                    flexWrap: "wrap",
                    gap: 0.5,
                    justifyContent: "center",
                  }}
                >
                  {tiles.map((tile) => {
                    const isHighlighted =
                      hoveredLetters.size > 0 &&
                      tile.letters.some((l) =>
                        hoveredLetters.has(normalizeLetter(l))
                      );
                    return (
                      <HebrewLetterTile
                        key={tile.id}
                        tile={tile}
                        userLanguage={userLanguage}
                        isOver={overId === tile.id && activeId !== tile.id}
                        isHighlighted={isHighlighted}
                        hebrewFont={HEBREW_FONT}
                        onDestructure={handleDestructure}
                        destructureTooltip={t("hebrewExplorer.clickToSplit")}
                      />
                    );
                  })}
                </Box>
              )}
            </Box>
          </DndContext>

          {tiles.length === 0 && !loading && (
            <Typography
              variant="body1"
              color="text.secondary"
              sx={{ mt: 4, textAlign: "center", maxWidth: 400 }}
            >
              {t("hebrewExplorer.noData")}
            </Typography>
          )}
        </>
      )}
    </Box>,
    document.body
  );
};

export default HebrewExplorer;
